/* xx_mh01_extractor.c - search raw data for D-Link MH01.
 *
 * Scans for:
 *   4D 48 30 31 at +0  ("MH01")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the mh01 reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/mh01/xx_mh01.h"

static const uint8_t k_anchor0[] = { 0x4D, 0x48, 0x30, 0x31 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_MH01 };

static Abstractformat *xx_mh01_search_open(xx_io_device *window) {
    xx_mh01 *reader = xx_mh01_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_mh01_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_mh01_free((xx_mh01 *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_mh01_search_open, xx_mh01_search_close
};

static xx_format_search_state *xx_mh01_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_mh01_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_mh01_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_mh01_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_mh01_extractor = {
    xx_mh01_create_format_search,
    xx_mh01_get_current_format_info,
    xx_mh01_format_search_find_next,
    xx_mh01_free_format_search
};
